def medianOfUniquenessArray(nums):
    n = len(nums)
    total = n * (n + 1) // 2  # Total number of subarrays
    medianPos = (total + 1) // 2  # 1-based index (if even, pick smaller)

    def subarraysWithAtMostKUnique(k):
        count = {}
        result = 0
        left = 0
        unique = 0
        for right in range(n):
            val = nums[right]
            count[val] = count.get(val, 0) + 1
            if count[val] == 1:
                unique += 1
            while unique > k:
                count[nums[left]] -= 1
                if count[nums[left]] == 0:
                    unique -= 1
                left += 1
            result += right - left + 1
        return result

    left, right = 1, n
    while left < right:
        mid = (left + right) // 2
        if subarraysWithAtMostKUnique(mid) >= medianPos:
            right = mid
        else:
            left = mid + 1
    return left
